#!/usr/bin/env python3
"""Own two-region diagnostic art and scalar maps; stdlib only, repository LICENSE.
--check compares generated bytes without modifying files.
"""
import argparse
from pathlib import Path
import struct
import zlib

WIDTH, HEIGHT = 960, 540
ROOT = Path(__file__).resolve().parents[1] / 'Test-Wallpaper/WSS-Ripple-Chain-v1/assets'


def png(rows):
    def chunk(kind, data):
        return struct.pack('>I', len(data)) + kind + data + struct.pack('>I', zlib.crc32(kind + data) & 0xffffffff)
    return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', WIDTH, HEIGHT, 8, 6, 0, 0, 0))
            + chunk(b'IDAT', zlib.compress(b''.join(rows), 9)) + chunk(b'IEND', b''))


def band(value, low, high, feather):
    return max(0, min(1, (value-low)/feather, (high-value)/feather))


def assets():
    background, mask_a, mask_b = [], [], []
    for y in range(HEIGHT):
        row, a, b = bytearray([0]), bytearray([0]), bytearray([0])
        for x in range(WIDTH):
            checker = ((x//16)+(y//16)) % 2
            color = [22+checker*10, 70+checker*14, 104+checker*20, 255]
            if x % 48 < 2 or y % 36 < 2:
                color = [125, 207, 215, 255]
            if (x % 96-48)**2+(y % 108-54)**2 < 20:
                color = [240, 212, 100, 255]
            # Top waterfall reaches into the broad lower basin: overlap y=280..330.
            va = round(255*band(x, 320, 480, 12)*band(y, 50, 330, 12))
            vb = round(255*band(x, 130, 850, 16)*band(y, 280, 500, 16))
            row.extend(color)
            a.extend([va, va, va, 255])
            b.extend([vb, vb, vb, 255])
        background.append(row)
        mask_a.append(a)
        mask_b.append(b)
    return {'background.png': png(background), 'mask-a.png': png(mask_a), 'mask-b.png': png(mask_b)}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    check = parser.parse_args().check
    if not check:
        ROOT.mkdir(parents=True, exist_ok=True)
    for name, data in assets().items():
        path = ROOT / name
        if check:
            if path.read_bytes() != data:
                raise SystemExit('Fixture differs: '+str(path))
        else:
            path.write_bytes(data)
        print(('Verified ' if check else 'Generated ')+str(path))


if __name__ == '__main__':
    main()
